namespace Warehouse;

public sealed class InventoryTracker
{
    private readonly Dictionary<string, int> _stock = new();

    public int ReorderThreshold { get; set; } = 5;

    public int GetStockLevel(string sku)
    {
        ValidateSku(sku);
        return _stock.TryGetValue(sku, out var level) ? level : 0;
    }

    public void AddStock(string sku, int quantity)
    {
        ValidateSku(sku);
        ValidateQuantity(quantity);

        if (_stock.ContainsKey(sku))
            _stock[sku] += quantity;
        else
            _stock[sku] = quantity;
    }

    public void RemoveStock(string sku, int quantity)
    {
        ValidateSku(sku);
        ValidateQuantity(quantity);

        var current = GetStockLevel(sku);
        if (current < quantity)
            throw new InvalidOperationException($"Insufficient stock for SKU '{sku}'. Current: {current}, Requested: {quantity}.");

        _stock[sku] = current - quantity;
    }

    public bool NeedsReorder(string sku)
    {
        ValidateSku(sku);
        return GetStockLevel(sku) <= ReorderThreshold;
    }

    public void TransferStock(string sku, int quantity, InventoryTracker destination)
    {
        ValidateSku(sku);
        ValidateQuantity(quantity);
        ArgumentNullException.ThrowIfNull(destination);

        RemoveStock(sku, quantity);
        destination.AddStock(sku, quantity);
    }

    private static void ValidateSku(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            throw new ArgumentNullException(nameof(sku), "SKU cannot be null or empty.");
    }

    private static void ValidateQuantity(int quantity)
    {
        if (quantity <= 0)
            throw new ArgumentException("Quantity must be greater than zero.", nameof(quantity));
    }
}

using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup()
    {
        _tracker = new InventoryTracker();
    }

    // --- Stock Level Tests ---

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN"));
    }

    [TestMethod]
    public void AddStock_IncreasesStockLevel()
    {
        _tracker.AddStock("SKU-001", 10);
        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void AddStock_MultipleTimes_Accumulates()
    {
        _tracker.AddStock("SKU-001", 10);
        _tracker.AddStock("SKU-001", 5);
        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void RemoveStock_DecreasesStockLevel()
    {
        _tracker.AddStock("SKU-001", 10);
        _tracker.RemoveStock("SKU-001", 3);
        Assert.AreEqual(7, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void RemoveStock_InsufficientStock_ThrowsInvalidOperationException()
    {
        _tracker.AddStock("SKU-001", 2);
        Assert.ThrowsException<InvalidOperationException>(() => _tracker.RemoveStock("SKU-001", 5));
    }

    [TestMethod]
    public void AddStock_ZeroQuantity_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.AddStock("SKU-001", 0));
    }

    [TestMethod]
    public void AddStock_NegativeQuantity_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.AddStock("SKU-001", -1));
    }

    [TestMethod]
    public void AddStock_NullSku_ThrowsArgumentNullException()
    {
        Assert.ThrowsException<ArgumentNullException>(() => _tracker.AddStock(null!, 1));
    }

    [TestMethod]
    public void AddStock_EmptySku_ThrowsArgumentNullException()
    {
        Assert.ThrowsException<ArgumentNullException>(() => _tracker.AddStock("", 1));
    }

    [TestMethod]
    public void RemoveStock_ZeroQuantity_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.RemoveStock("SKU-001", 0));
    }

    [TestMethod]
    public void RemoveStock_NegativeQuantity_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _tracker.RemoveStock("SKU-001", -1));
    }

    [TestMethod]
    public void RemoveStock_NullSku_ThrowsArgumentNullException()
    {
        Assert.ThrowsException<ArgumentNullException>(() => _tracker.RemoveStock(null!, 1));
    }

    [TestMethod]
    public void RemoveStock_EmptySku_ThrowsArgumentNullException()
    {
        Assert.ThrowsException<ArgumentNullException>(() => _tracker.RemoveStock("", 1));
    }

    // --- Reorder Alert Tests ---

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-001", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-001", 3);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-001", 10);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-001"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("UNKNOWN"));
    }

    [TestMethod]
    public void NeedsReorder_CustomThreshold_IsRespected()
    {
        _tracker.ReorderThreshold = 20;
        _tracker.AddStock("SKU-001", 15);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));

        _tracker.AddStock("SKU-001", 10);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-001"));
    }

    // --- Transfer Tests ---

    [TestMethod]
    public void TransferStock_MovesStockBetweenTrackers()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-001", 10);

        _tracker.TransferStock("SKU-001", 4, destination);

        Assert.AreEqual(6, _tracker.GetStockLevel("SKU-001"));
        Assert.AreEqual(4, destination.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void TransferStock_InsufficientStock_ThrowsInvalidOperationException()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-001", 2);

        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-001", 5, destination));
    }

    [TestMethod]
    public void TransferStock_NullDestination_ThrowsArgumentNullException()
    {
        _tracker.AddStock("SKU-001", 10);
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.TransferStock("SKU-001", 1, null!));
    }

    [TestMethod]
    public void TransferStock_ZeroQuantity_ThrowsArgumentException()
    {
        var destination = new InventoryTracker();
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.TransferStock("SKU-001", 0, destination));
    }

    [TestMethod]
    public void TransferStock_NegativeQuantity_ThrowsArgumentException()
    {
        var destination = new InventoryTracker();
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.TransferStock("SKU-001", -1, destination));
    }

    [TestMethod]
    public void TransferStock_SourceDecreasesAndDestinationIncreases()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-001", 20);
        destination.AddStock("SKU-001", 5);

        _tracker.TransferStock("SKU-001", 8, destination);

        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-001"));
        Assert.AreEqual(13, destination.GetStockLevel("SKU-001"));
    }
}

